namespace views = std::views;

struct Order { std::vector<Line> lines; };

auto big_lines = orders
    | views::transform(&Order::lines)          // map: Order -> its lines
    | views::join                              // bind: flatten to one range
    | views::filter([](const Line& l) { return l.qty > 100; });

task<Report> generate(Repo& repo, UserId id) {
    auto user = co_await repo.fetch_user(id);    // bind: resumes with the value
    auto orders = co_await repo.orders(user);    // depends on user
    co_return summarize(user, orders);
}
